input.command:
REPO_OWNER=$(gh repo view --json owner --jq '.owner.login') && REPO_NAME=$(gh repo view --json name --jq '.name') && echo "$REPO_OWNER/$REPO_NAME" && gh api graphql -f query="
{
  repository(owner: \"$REPO_OWNER\", name: \"$REPO_NAME\") {
    pullRequest(number: 258) {
      reviewThreads(first: 100) {
        nodes {
          id
          isResolved
          comments(first: 10) {
            nodes {
              id
              databaseId
              author { login }
              body
              path
              line
              createdAt
            }
          }
        }
      }
    }
  }
}"

gh api graphql -f query='
mutation {
  t1: resolveReviewThread(input: {threadId: "PRRT_kwDOQ6DXvM5x5nfa"}) {
    thread { isResolved }
  }
  t2: resolveReviewThread(input: {threadId: "PRRT_kwDOQ6DXvM5x5nf2"}) {
    thread { isResolved }
  }
}'
